<?php use App\Core\Security; ?><h4>تنظیم اعلان‌ها</h4><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><?php foreach($rows as $r):?><div class="row border-bottom py-2"><div class="col-md-4"><?=Security::e($r['title'])?></div><div class="col-md-3"><select name="rules[<?=Security::e($r['rule_key'])?>][enabled]" class="form-select"><option value="1" <?=$r['is_enabled']?'selected':''?>>فعال</option><option value="0" <?=!$r['is_enabled']?'selected':''?>>غیرفعال</option></select></div><div class="col-md-3"><select name="rules[<?=Security::e($r['rule_key'])?>][channel]" class="form-select"><option value="panel" <?=$r['channel']==='panel'?'selected':''?>>داخل پنل</option><option value="email" <?=$r['channel']==='email'?'selected':''?>>ایمیل</option></select></div><div class="col-md-2"><input name="rules[<?=Security::e($r['rule_key'])?>][recipients]" value="<?=Security::e($r['recipients']??'')?>" class="form-control" placeholder="ایمیل گیرندگان"></div></div><?php endforeach;?><button class="btn btn-primary mt-3">ذخیره</button></form>